#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

using pii = pair<int, int>;
using ll = long long;

mt19937_64 gen(chrono::steady_clock::now().time_since_epoch().count());

const int MAXN = 12;
const int INF = 1000000009;
const int DIRS = 4;
const int dx[DIRS] = {0, 1, 0, -1};
const int dy[DIRS] = {1, 0, -1, 0};

int N, T;
char A[MAXN][MAXN], B[MAXN][MAXN];
int dist[MAXN][MAXN];
bool vis[MAXN][MAXN];

struct Pos {
    int x, y;
    Pos() {}
    Pos(int x, int y) : x(x), y(y) {}
};

void bfs(int sx, int sy) {
    for (int i = 0; i < N; ++i) fill(dist[i], dist[i] + N, INF);
    memset(vis, 0, sizeof(vis));
    queue<Pos> q;
    vis[sx][sy] = true;
    dist[sx][sy] = 0;
    q.emplace(sx, sy);
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        for (int i = 0; i < DIRS; ++i) {
            int nx = cur.x + dx[i], ny = cur.y + dy[i];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !vis[nx][ny] && isdigit(A[nx][ny])) {
                vis[nx][ny] = true;
                dist[nx][ny] = dist[cur.x][cur.y] + 1;
                q.emplace(nx, ny);
            }
        }
    }
}

bool dp[72][12][12][12][12];
bool ok[12][12][12][12];

int cap[290][290];
int par[290];
bool visited[290];

bool bfs_dinic() {
    memset(visited, 0, sizeof(visited));
    memset(par, 0, sizeof(par));
    queue<int> q;
    visited[0] = true;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == 2 * N * N + 1) return true;
        for (int v = 0; v <= 2 * N * N + 1; ++v) {
            if (cap[u][v] && !visited[v]) {
                visited[v] = true;
                par[v] = u;
                q.push(v);
            }
        }
    }
    return false;
}

void process() {
    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];
    int sx = -1, sy = -1;
    cin >> sx >> sy;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (A[i][j] == 'Z') {
                sx = i; sy = j;
            }
        }
    }
    bfs(sx, sy);
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(A[i][j])) {
                dp[0][i][j][i][j] = true;
            }
        }
    }
    for (int t = 0; t < T; ++t) {
        for (int px = 0; px < N; ++px) {
            for (int py = 0; py < N; ++py) {
                for (int x = 0; x < N; ++x) {
                    for (int y = 0; y < N; ++y) {
                        if (!dp[t][px][py][x][y]) continue;
                        if (dist[x][y] <= t) continue;
                        for (int d = 0; d < DIRS; ++d) {
                            int nx = x + dx[d], ny = y + dy[d];
                            if (nx >= 0 && nx < N && ny >= 0 && ny < N && isdigit(A[nx][ny]) && dist[nx][ny] >= t + 1) {
                                dp[t + 1][px][py][nx][ny] = true;
                            }
                        }
                    }
                }
            }
        }
    }
    memset(ok, 0, sizeof(ok));
    for (int t = 0; t <= T; ++t) {
        for (int px = 0; px < N; ++px) {
            for (int py = 0; py < N; ++py) {
                for (int x = 0; x < N; ++x) {
                    for (int y = 0; y < N; ++y) {
                        if (dp[t][px][py][x][y]) {
                            ok[px][py][x][y] = true;
                        }
                    }
                }
            }
        }
    }
    memset(cap, 0, sizeof(cap));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(A[i][j])) {
                cap[0][i * N + j + 1] = A[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(B[i][j])) {
                cap[N * N + i * N + j + 1][2 * N * N + 1] = B[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!isdigit(A[i][j])) continue;
            for (int k = 0; k < N; ++k) {
                for (int l = 0; l < N; ++l) {
                    if (!isdigit(A[k][l])) continue;
                    if (!ok[i][j][k][l]) continue;
                    cap[i * N + j + 1][N * N + k * N + l + 1] = INF;
                }
            }
        }
    }
    while (bfs_dinic()) {
        int f = INF;
        for (int u = 2 * N * N + 1; u; u = par[u]) {
            f = min(f, cap[par[u]][u]);
        }
        for (int u = 2 * N * N + 1; u; u = par[u]) {
            cap[par[u]][u] -= f;
            cap[u][par[u]] += f;
        }
    }
    int total = 0;
    for (int i = 0; i <= 2 * N * N + 1; ++i) {
        total += cap[i][0];
    }
    cout << total << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    process();
    return 0;
}
